				return existing_value('translational_r_d_content_table', 'img1', Request::val('SelectedID'));
			},
		]),
		'img2' => Request::fileUpload('img2', [
			'maxSize' => 10240000,
			'types' => 'jpg|jpeg|gif|png|webp',
			'noRename' => false,
			'dir' => '',
